// Fails on a tracked file over 5,000 tokens (tokens = bytes / 4) that
// .token-ceilings does not list, and on a listed file past its ceiling. It also
// fails on a list entry that names no tracked file, or a file now at or under
// the limit, so the list holds only files that need a ceiling. It uses
// the rules of the token-limit pre-commit hook, and skips the files the hook
// skips: lockfiles, built and generated files, binaries, and files marked
// linguist-generated in .gitattributes.
//
// Where that hook is installed, the check also runs the hook's own --scan and
// fails when the two find different files. TOKEN_LIMIT_HOOK names the hook's
// script. Without it, the check follows this repo's pre-commit hook to the
// script it runs.
//
// Usage: node scripts/check-sizes.mjs

import { execFileSync, spawnSync } from 'node:child_process'
import { existsSync, lstatSync, readFileSync } from 'node:fs'
import { homedir } from 'node:os'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..')
const CEILINGS_FILE = '.token-ceilings'
const TOKEN_LIMIT = 5_000
const BYTES_PER_TOKEN = 4
const HEAD_BYTES = 2048
const SCAN_HEADER = 'token-limit-scan 1'

const LOCKFILE_NAMES = new Set([
  'package-lock.json',
  'npm-shrinkwrap.json',
  'pnpm-lock.yaml',
  'yarn.lock',
  'bun.lock',
  'bun.lockb',
  'deno.lock',
  'Cargo.lock',
  'Gemfile.lock',
  'poetry.lock',
  'uv.lock',
  'Pipfile.lock',
  'composer.lock',
  'go.sum',
  'Package.resolved',
  'Podfile.lock',
  'flake.lock',
  'mix.lock',
  'pubspec.lock',
  'packages.lock.json',
])
const GENERATED_SUFFIXES = [
  '.lock',
  '.min.js',
  '.min.css',
  '.map',
  '.snap',
  '.pbxproj',
  '.xcworkspacedata',
  '.generated.ts',
  '.generated.js',
  '.g.dart',
  '.pb.go',
  '_pb2.py',
  '.pb.swift',
]
const GENERATED_DIRS = new Set([
  'dist',
  'build',
  'out',
  'generated',
  '__generated__',
  '__snapshots__',
  'node_modules',
  'vendor',
  '.next',
  'DerivedData',
])
const GENERATED_MARKER = /@generated|do not edit|auto-?generated|code generated by/i

const git = (...args) => execFileSync('git', args, { cwd: ROOT, maxBuffer: 64 * 1024 * 1024 })

function skippedByName(path) {
  const parts = path.split('/')
  const name = parts.pop()
  return (
    LOCKFILE_NAMES.has(name) ||
    GENERATED_SUFFIXES.some(suffix => name.endsWith(suffix)) ||
    parts.some(part => GENERATED_DIRS.has(part))
  )
}

function markedGenerated(paths) {
  if (paths.length === 0) return new Set()
  const fields = git('check-attr', '-z', 'linguist-generated', '--', ...paths)
    .toString()
    .split('\0')
  const generated = new Set()
  for (let i = 0; i + 2 < fields.length; i += 3)
    if (fields[i + 2] === 'set' || fields[i + 2] === 'true') generated.add(fields[i])
  return generated
}

function parseCeilings(text) {
  const ceilings = new Map()
  for (const [index, line] of text.split('\n').entries()) {
    const entry = line.replace(/^[ \t\r]+|[ \t\r]+$/g, '')
    if (entry === '' || entry.startsWith('#')) continue
    const fields = entry.split(/[ \t]+/)
    const where = `${CEILINGS_FILE}:${index + 1}`
    if (fields.length !== 2 || !/^[0-9]+$/.test(fields[1]))
      throw new Error(`${where}: expected "path ceiling", such as "src/app.ts 6000", got: ${entry}`)
    const [path, ceiling] = fields
    if (ceilings.has(path)) throw new Error(`${where}: ${path} is listed twice`)
    ceilings.set(path, Number(ceiling))
  }
  return ceilings
}

function readCeilings() {
  const path = join(ROOT, CEILINGS_FILE)
  if (!existsSync(path)) return new Map()
  let text
  try {
    text = new TextDecoder('utf-8', { fatal: true }).decode(readFileSync(path))
  } catch {
    throw new Error(`${CEILINGS_FILE}: not UTF-8 text`)
  }
  return parseCeilings(text)
}

const trackedFiles = () =>
  git('ls-files', '-z')
    .toString()
    .split('\0')
    .filter(path => path !== '')

function staleEntries(ceilings, tracked) {
  const stale = []
  for (const path of ceilings.keys()) {
    const full = join(ROOT, path)
    if (!tracked.has(path) || !existsSync(full))
      stale.push(`${CEILINGS_FILE} lists ${path}, which is not a tracked file.`)
    else if (Math.floor(lstatSync(full).size / BYTES_PER_TOKEN) <= TOKEN_LIMIT)
      stale.push(
        `${CEILINGS_FILE} lists ${path}, which is now at or under the ${TOKEN_LIMIT.toLocaleString('en-US')}-token limit.`,
      )
  }
  return stale.map(problem => `${problem} Remove its entry.`)
}

function filesOverLimit(ceilings, tracked) {
  const paths = tracked.filter(path => !skippedByName(path))
  const generated = markedGenerated(paths)
  const over = []
  for (const path of paths) {
    const full = join(ROOT, path)
    if (generated.has(path) || !existsSync(full) || !lstatSync(full).isFile()) continue
    const data = readFileSync(full)
    const tokens = Math.floor(data.length / BYTES_PER_TOKEN)
    const ceiling = ceilings.get(path)
    if (tokens <= TOKEN_LIMIT || (ceiling !== undefined && tokens <= ceiling)) continue
    const head = data.subarray(0, HEAD_BYTES)
    if (head.includes(0) || GENERATED_MARKER.test(head.toString('latin1'))) continue
    over.push({ path, tokens, ceiling })
  }
  return over
}

function installedHook() {
  if (process.env.TOKEN_LIMIT_HOOK) return process.env.TOKEN_LIMIT_HOOK
  const preCommit = resolve(ROOT, git('rev-parse', '--git-path', 'hooks/pre-commit').toString().trim())
  if (!existsSync(preCommit)) return undefined
  const target = readFileSync(preCommit, 'utf8').match(/exec "([^"]*token-limit-pre-commit)"/)?.[1]
  return target?.replace(/^\$HOME(?=\/)/, homedir())
}

function hookScan(hook) {
  const run = spawnSync('python3', [hook, '--scan'], { cwd: ROOT, encoding: 'utf8' })
  if (run.status !== 0) throw new Error(`The hook's --scan failed (${hook}):\n${run.stderr || run.error}`)
  const [header, ...lines] = run.stdout.split('\n')
  if (header !== SCAN_HEADER) throw new Error(`The hook at ${hook} has no --scan. Update it.`)
  return lines
    .filter(line => line !== '')
    .map(line => {
      const [path, tokens] = line.split('\t')
      return { path, tokens: Number(tokens) }
    })
}

const describe = ({ path, tokens }) => `${path} (${tokens.toLocaleString('en-US')} tokens)`

function differences(ours, hooks) {
  const key = file => `${file.path}\t${file.tokens}`
  const hookKeys = new Set(hooks.map(key))
  const ourKeys = new Set(ours.map(key))
  return [
    ...ours.filter(file => !hookKeys.has(key(file))).map(file => `only this check finds ${describe(file)}`),
    ...hooks.filter(file => !ourKeys.has(key(file))).map(file => `only the hook finds ${describe(file)}`),
  ]
}

const problems = []
try {
  const ceilings = readCeilings()
  const tracked = trackedFiles()
  problems.push(...staleEntries(ceilings, new Set(tracked)))
  const over = filesOverLimit(ceilings, tracked)
  for (const file of over)
    problems.push(
      file.ceiling === undefined
        ? `${describe(file)} is over the ${TOKEN_LIMIT.toLocaleString('en-US')}-token limit. Split it into smaller files.`
        : `${describe(file)} is past its ceiling of ${file.ceiling.toLocaleString('en-US')} in ${CEILINGS_FILE}. Move code out of it.`,
    )
  const hook = installedHook()
  if (hook !== undefined) {
    if (!existsSync(hook)) throw new Error(`The token-limit hook is not at ${hook}.`)
    for (const difference of differences(over, hookScan(hook)))
      problems.push(`This check and the token-limit hook disagree: ${difference}. Make their rules match.`)
  }
} catch (error) {
  problems.push(error.message)
}

if (problems.length > 0) {
  for (const problem of problems) console.error(problem)
  process.exit(1)
}
